package cn.sifangguan.hotelaios.finance;

import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Internal bridge from verified procurement, physical stock and controlled accrual facts. No public amount injection. */
public final class FinanceBudgetBridge {
 private final NamedParameterJdbcTemplate jdbc;private final FinanceControlGuard guard;
 public FinanceBudgetBridge(NamedParameterJdbcTemplate jdbc){this.jdbc=jdbc;this.guard=new FinanceControlGuard(jdbc);}
 private boolean installed(){return guard.table("fbu_flow")&&guard.table("fs_procurement_finance_classification");}
 private Map<String,Object> one(TenantPrincipal p,String sql,UUID id){var rows=jdbc.queryForList(sql,base(p).addValue("id",id));if(rows.size()!=1)throw conflict("预算承接的真实业务来源不存在或不唯一");return rows.getFirst();}
 private UUID company(TenantPrincipal p,UUID hotel){var rows=jdbc.queryForList("select company_id from finance_store_config where tenant_id=:tenant and hotel_id=:hotel and enabled",base(p).addValue("hotel",hotel));return rows.size()==1?id(rows.getFirst().get("company_id")):null;}
 private LocalDate day(Object value){if(value instanceof java.sql.Date date)return date.toLocalDate();if(value instanceof java.util.Date date)return date.toInstant().atZone(ZoneId.of("Asia/Shanghai")).toLocalDate();if(value instanceof OffsetDateTime date)return date.atZoneSameInstant(ZoneId.of("Asia/Shanghai")).toLocalDate();return LocalDate.parse(value.toString().substring(0,10));}
 private static BigDecimal money(Object value){return amount(value).setScale(2,RoundingMode.HALF_UP);}
 private static UUID key(String value){return UUID.nameUUIDFromBytes(value.getBytes(StandardCharsets.UTF_8));}
 private String linesSql(){return "select l.*,coalesce(l.financial_category_code,c.financial_category_code) finance_code,coalesce(l.financial_department_id,c.financial_department_id) finance_department"+(FinanceCostDimensions.projectsInstalled(jdbc)?",case when l.project_kind<>'NONE' then l.project_snapshot else coalesce(c.project_snapshot,l.project_snapshot) end finance_project_snapshot":"")+" from procurement_line l left join fs_procurement_finance_classification c on c.tenant_id=l.tenant_id and c.line_id=l.id";}
 private void scope(UUID hotel){new AccessPolicy().requireOrgScope(hotel);}
 private void issue(TenantPrincipal p,String kind,UUID source,UUID hotel,String message){jdbc.update("insert into fbu_issue(tenant_id,source_kind,source_id,hotel_id,message,status) values(:tenant,:kind,:source,:hotel,:message,'OPEN') on conflict(tenant_id,source_kind,source_id) do update set message=excluded.message,status='OPEN',updated_at=now()",base(p).addValue("kind",kind).addValue("source",source).addValue("hotel",hotel).addValue("message",message));}
 private void resolved(TenantPrincipal p,String kind,UUID source){jdbc.update("update fbu_issue set status='RESOLVED',updated_at=now() where tenant_id=:tenant and source_kind=:kind and source_id=:source and status='OPEN'",base(p).addValue("kind",kind).addValue("source",source));}
 public void procurement(TenantPrincipal p,UUID orderId,String phase){if(!installed())return;if(!Set.of("SUBMIT","APPROVE","RELEASE","REFRESH").contains(phase))throw bad("未知预算承诺阶段");var order=one(p,"select * from procurement_order where tenant_id=:tenant and id=:id",orderId);UUID hotel=id(order.get("hotel_id"));scope(hotel);UUID company=company(p,hotel);if(company==null){issue(p,"PROCUREMENT",orderId,hotel,"真实法人映射缺失，采购预算待核对；未把未知主体金额当作零");return;}
  LocalDate day=day(order.get("created_at"));var lines=jdbc.queryForList(linesSql()+" where l.tenant_id=:tenant and l.order_id=:id order by l.id",base(p).addValue("id",orderId));boolean missing=false;
  for(var line:lines){String code=Objects.toString(line.get("finance_code"),"");if(code.isBlank()||line.get("finance_department")==null){missing=true;if(Set.of("SUBMIT","APPROVE").contains(phase)&&hasBudget(p,hotel,day))throw conflict("已配置财务预算，采购行必须明确财务成本类别；不能按物品分类猜测或绕过预算");continue;}
   if(line.get("unit_price")==null&&line.get("budget_unit_price")==null){missing=true;if(Set.of("SUBMIT","APPROVE").contains(phase)&&hasBudget(p,hotel,day))throw conflict("已发布预算要求申请明确预估单价；未知价格不能按零金额绕过预算");continue;}UUID lineId=id(line.get("id"));String nature=nature(line.get("line_kind"));BigDecimal factor=amount(line.get("factor"));if(factor.signum()<=0)throw conflict("原采购单位换算无效，不可计算预算");BigDecimal basePrice=amount(line.get("unit_price")==null?line.get("budget_unit_price"):line.get("unit_price")).divide(factor,12,RoundingMode.HALF_UP);BigDecimal ordered=money(amount(line.get("quantity")).multiply(basePrice));BigDecimal financialQuantity=jdbc.queryForObject("select coalesce(sum(rl.accepted),0) from procurement_receipt_line rl join procurement_receipt r on r.tenant_id=rl.tenant_id and r.id=rl.receipt_id join fs_recognition f on f.tenant_id=r.tenant_id and f.receipt_id=r.id where rl.tenant_id=:tenant and rl.line_id=:line and r.status='APPROVED' and f.status in ('ESTIMATED','CONFIRMED','REPLACED')",base(p).addValue("line",lineId),BigDecimal.class);BigDecimal fulfilled=money(financialQuantity.min(amount(line.get("quantity"))).multiply(basePrice));BigDecimal remaining=ordered.subtract(fulfilled).max(BigDecimal.ZERO);
   put(p,"PROCUREMENT",orderId,lineId,orderId,hotel,company,day,code,id(line.get("finance_department")),nature,phase.equals("SUBMIT")?remaining:BigDecimal.ZERO,Set.of("APPROVE","REFRESH").contains(phase)?remaining:BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,((Number)order.get("version")).longValue(),Map.of("phase",phase,"orderedAmount",ordered.toPlainString(),"fulfilledPurchaseAmount",fulfilled.toPlainString(),"projectSnapshot",projectOf(line)),Set.of("SUBMIT","APPROVE").contains(phase));
  }if(missing)issue(p,"PROCUREMENT",orderId,hotel,"存在历史未归类或缺少明确价格的采购行，未默认推断类别/部门或把未知金额算零");else resolved(p,"PROCUREMENT",orderId);
 }
 private static String nature(Object kind){return switch(Objects.toString(kind)){case "ASSET","PROJECT"->"CAPITAL";case "INVENTORY"->"INVENTORY";default->"EXPENSE";};}
 private boolean hasBudget(TenantPrincipal p,UUID hotel,LocalDate day){return jdbc.queryForObject("select count(*) from fc_policy where tenant_id=:tenant and hotel_id=:hotel and kind='BUDGET' and status='PUBLISHED' and spec->>'month'=:month",base(p).addValue("hotel",hotel).addValue("month",YearMonth.from(day).toString()),Integer.class)>0;}
 public void recognition(TenantPrincipal p,UUID recognition){if(!installed())return;var source=one(p,"select f.*,r.order_id from fs_recognition f join procurement_receipt r on r.tenant_id=f.tenant_id and r.id=f.receipt_id where f.tenant_id=:tenant and f.id=:id",recognition);if(!Set.of("ESTIMATED","CONFIRMED").contains(source.get("status")))return;UUID hotel=id(source.get("hotel_id"));scope(hotel);LocalDate day=day(source.get("accounting_date"));var lines=jdbc.queryForList(linesSql()+" join procurement_receipt_line rl on rl.tenant_id=l.tenant_id and rl.line_id=l.id where rl.tenant_id=:tenant and rl.receipt_id=:id and rl.accepted>0 order by l.id",base(p).addValue("id",source.get("receipt_id")));boolean missing=false;procurement(p,id(source.get("order_id")),"REFRESH");
  for(var line:lines){String code=Objects.toString(line.get("finance_code"),"");if(code.isBlank()||line.get("finance_department")==null){missing=true;continue;}UUID lineId=id(line.get("id"));String nature=nature(line.get("line_kind"));UUID event=key(recognition+":"+source.get("version"));var basis=base(p).addValue("document",recognition).addValue("line",lineId).addValue("lineText",lineId.toString()).addValue("event",event);
   // Follow actual rounded ledger sources, including cumulative 4dp estimate tails and signed later price corrections.
   BigDecimal target=jdbc.queryForObject("select coalesce(sum(case when event_key like 'ADJUST_DOWN%' then -amount else amount end),0) from fa_source_event where tenant_id=:tenant and source_type='FS_PROCUREMENT' and source_id=:document and metadata->>'lineId'=:lineText",basis,BigDecimal.class);
   // Exact-version replay must not subtract its own already frozen delta.
   BigDecimal previous=jdbc.queryForObject("select coalesce(sum(case when basis_kind='INVENTORY' then inventory_value else actual end),0) from fbu_flow where tenant_id=:tenant and source_kind='RECEIPT' and document_id=:document and line_id=:line and source_id<>:event",basis,BigDecimal.class);BigDecimal delta=money(target).subtract(previous);
   put(p,"RECEIPT",event,lineId,recognition,hotel,id(source.get("company_id")),day,code,id(line.get("finance_department")),nature,BigDecimal.ZERO,BigDecimal.ZERO,nature.equals("INVENTORY")?BigDecimal.ZERO:delta,nature.equals("INVENTORY")?delta:BigDecimal.ZERO,((Number)source.get("version")).longValue(),Map.of("recognitionId",recognition,"receiptId",source.get("receipt_id"),"targetRecognized",target.toPlainString(),"priorRecorded",previous.toPlainString(),"projectSnapshot",projectOf(line)),false);
  }for(var cost:jdbc.queryForList("select id from fa_source_event where tenant_id=:tenant and source_type='FS_PROCUREMENT' and source_id=:id and metadata->>'nature'='CONSUMED_PRICE_ADJUSTMENT'",base(p).addValue("id",recognition)))priceAdjustment(p,id(cost.get("id")));if(missing)issue(p,"RECEIPT",recognition,hotel,"已发生采购核算有未归类行，需要财务按真实来源追加归类，未隐去成本");else resolved(p,"RECEIPT",recognition);
 }
 public void inventory(TenantPrincipal p,UUID movement){if(!installed())return;var row=one(p,"select m.*,e.company_id,e.book_amount,"+(FinanceCostDimensions.projectsInstalled(jdbc)?"case when m.project_kind<>'NONE' then m.project_snapshot else coalesce(c.project_snapshot,m.project_snapshot) end finance_project_snapshot,":"")+"coalesce(m.financial_category_code,c.financial_category_code) finance_code,coalesce(m.financial_department_id,c.financial_department_id) finance_department,coalesce(s.posting_date,(m.occurred_at at time zone 'Asia/Shanghai')::date) finance_date from store_inventory_movement m join fs_inventory_event e on e.tenant_id=m.tenant_id and e.movement_id=m.id left join fs_movement_finance_classification c on c.tenant_id=m.tenant_id and c.movement_id=m.id left join store_cost_entry s on s.tenant_id=m.tenant_id and s.source_id=m.id and s.source_kind='INVENTORY' where m.tenant_id=:tenant and m.id=:id",movement);UUID hotel=id(row.get("hotel_org_unit_id"));scope(hotel);if(Set.of("PROCUREMENT","PROCUREMENT_RETURN").contains(row.get("source_type")))return;
  String code=Objects.toString(row.get("finance_code"),"");UUID department=id(row.get("finance_department"));if(code.isBlank()||department==null){issue(p,"INVENTORY",movement,hotel,"实际领用成本缺明确财务类别或实际使用部门，等待财务追加归类；不将库存采购当费用，也不把未归类消耗当作零");return;}
  put(p,"INVENTORY",movement,movement,movement,hotel,id(row.get("company_id")),day(row.get("finance_date")),code,department,"EXPENSE",BigDecimal.ZERO,BigDecimal.ZERO,money(row.get("book_amount")),BigDecimal.ZERO,0,Map.of("movementId",movement,"sourceType",row.get("source_type"),"projectSnapshot",projectOf(row)),false);resolved(p,"INVENTORY",movement);
 }
 public void returnReviewed(TenantPrincipal p,UUID returnId){if(!installed())return;var row=one(p,"select x.*,r.company_id,r.receipt_id from fs_return x join fs_recognition r on r.tenant_id=x.tenant_id and r.id=x.recognition_id where x.tenant_id=:tenant and x.id=:id",returnId);if(!"APPROVED".equals(row.get("status"))||"EXCHANGE".equals(row.get("kind")))return;var line=one(p,linesSql()+" where l.tenant_id=:tenant and l.id=:id",id(row.get("line_id")));UUID hotel=id(row.get("hotel_id"));scope(hotel);String code=Objects.toString(line.get("finance_code"),"");if(code.isBlank()||line.get("finance_department")==null){issue(p,"RETURN",returnId,hotel,"退货原行未有冻结成本分类，待财务追加核对");return;}String nature=nature(line.get("line_kind"));LocalDate day=day(row.get("accounting_date"));BigDecimal reverse=money(row.get("supplier_credit")).negate();put(p,"RETURN",returnId,id(row.get("line_id")),id(row.get("recognition_id")),hotel,id(row.get("company_id")),day,code,id(line.get("finance_department")),nature,BigDecimal.ZERO,BigDecimal.ZERO,nature.equals("INVENTORY")?BigDecimal.ZERO:reverse,nature.equals("INVENTORY")?reverse:BigDecimal.ZERO,((Number)row.get("version")).longValue(),Map.of("returnId",returnId,"recognitionId",row.get("recognition_id"),"projectSnapshot",projectOf(line)),false);resolved(p,"RETURN",returnId);}
 public void accrual(TenantPrincipal p,UUID runId){
  if(!installed())return;var run=one(p,"select r.*,p.hotel_id,p.company_id,p.book_id,p.source_document_id from far_run r join far_plan p on p.tenant_id=r.tenant_id and p.id=r.plan_id where r.tenant_id=:tenant and r.id=:id",runId);UUID hotel=id(run.get("hotel_id"));scope(hotel);var shares=rows(run.get("allocation_snapshot"));BigDecimal total=shares.stream().map(s->amount(s.get("amount"))).reduce(BigDecimal.ZERO,BigDecimal::add);if(total.compareTo(amount(run.get("amount")))!=0)throw conflict("真实月度分配与原核算金额不守恒，不投影虚假预算成本");
  for(var share:shares){String code=Objects.toString(share.get("financialCategoryCode"),"");UUID department=id(share.get("departmentId"));if(code.isBlank()||department==null){issue(p,"ACCRUAL",runId,hotel,"本期实际待摊/租赁费用缺明确类别/真实受益部门，需独立修订后核对；期初资金承接不等于本期费用已归类");return;}}
  transferContractCommitment(p,run,shares);for(var share:shares){UUID department=id(share.get("departmentId"));put(p,"ACCRUAL",runId,department,id(run.get("plan_id")),hotel,id(run.get("company_id")),day(run.get("month")),share.get("financialCategoryCode").toString(),department,"EXPENSE",BigDecimal.ZERO,BigDecimal.ZERO,money(share.get("amount")),BigDecimal.ZERO,0,Map.of("runId",runId,"revisionId",run.get("revision_id"),"planId",run.get("plan_id"),"allocationSnapshot",share,"noNewCashOrAcquisition",true,"projectSnapshot",projectOf(share)),false);}
  resolved(p,"ACCRUAL",runId);
 }
 private void transferContractCommitment(TenantPrincipal p,Map<String,Object> run,List<Map<String,Object>> shares){
  UUID source=id(run.get("source_document_id"));if(source==null)return;
  var b=base(p).addValue("source",source).addValue("run",run.get("id"));
  if(jdbc.queryForObject("select count(*) from fo_document where tenant_id=:tenant and id=:source and type='CONTRACT'",b,Long.class)==0)return;
  // The enclosing accrual operation already locks its real FO source before the plan/book. Never reverse that order here.
  jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(:key,103))",b.addValue("key",p.tenantId()+":financial-budget"),Object.class);
  if(jdbc.queryForObject("select count(*) from fc_event where tenant_id=:tenant and source_kind='ACCRUAL' and source_id=:run and event='BUDGET_ACCRUAL_TRANSFER'",b,Long.class)>0)return;
  var usage=jdbc.queryForList("select u.*,q.spec,q.code policy_code from fc_budget_usage u join fc_policy q on q.tenant_id=u.tenant_id and q.id=u.policy_id where u.tenant_id=:tenant and u.source_kind='OPERATION' and u.source_id=:source and u.state<>'RELEASED' and q.kind='BUDGET' order by u.policy_id for update of u",b);
  var changes=new ArrayList<Map<String,Object>>();
  for(var row:usage){var spec=map(row.get("spec"));if(!"EXPENSE".equals(spec.get("budgetKind")))continue;BigDecimal transfer=shares.stream().filter(s->Objects.equals(s.get("financialCategoryCode"),spec.get("categoryCode"))&&projectMatches(spec,Objects.toString(projectOf(s).get("key"),"NONE"))&&(Objects.toString(spec.get("departmentId"),"").isBlank()||Objects.equals(id(s.get("departmentId")),id(spec.get("departmentId"))))).map(s->amount(s.get("amount"))).reduce(BigDecimal.ZERO,BigDecimal::add);if(transfer.signum()==0)continue;
   if(!"COMMITTED".equals(row.get("state"))||amount(row.get("amount")).compareTo(transfer)<0){issue(p,"ACCRUAL_COMMITMENT",id(run.get("id")),id(run.get("hotel_id")),"原合同已存在匹配费用预算占用，但不是足额待履约承诺；保留本期真实费用并列待核对，不把旧实际改写或把不足当零");return;}
   changes.add(Map.of("policyId",row.get("policy_id"),"originalPolicyMonth",spec.get("month"),"before",amount(row.get("amount")).toPlainString(),"transferred",transfer.toPlainString(),"after",amount(row.get("amount")).subtract(transfer).toPlainString(),"oldSnapshot",map(row.get("snapshot"))));
  }
  for(var change:changes){var snapshot=new LinkedHashMap<>(map(change.get("oldSnapshot")));snapshot.put("lastAccrualTransfer",Map.of("runId",run.get("id"),"actualMonth",day(run.get("month")).toString(),"transferred",change.get("transferred"),"remainingCommitment",change.get("after")));jdbc.update("update fc_budget_usage set amount=:remaining,snapshot=cast(:snapshot as jsonb),updated_at=now() where tenant_id=:tenant and policy_id=:policy and source_kind='OPERATION' and source_id=:source",b.addValue("remaining",amount(change.get("after"))).addValue("policy",change.get("policyId")).addValue("snapshot",json(snapshot)));}
  guard.event(p,id(run.get("hotel_id")),"ACCRUAL",id(run.get("id")),"BUDGET_ACCRUAL_TRANSFER",Map.of("sourceContractId",source,"runId",run.get("id"),"actualMonth",day(run.get("month")).toString(),"originalCommitmentChanges",changes,"noNewPurchaseOrCash",true));resolved(p,"ACCRUAL_COMMITMENT",id(run.get("id")));
 }
 public void priceAdjustment(TenantPrincipal p,UUID eventId){
  if(!installed())return;var event=one(p,"select e.*,f.company_id source_company_id,a.allocations from fa_source_event e join fs_recognition f on f.tenant_id=e.tenant_id and f.id=e.source_id left join fs_price_cost_allocation a on a.tenant_id=e.tenant_id and a.source_event_id=e.id where e.tenant_id=:tenant and e.id=:id and e.source_type='FS_PROCUREMENT' and e.metadata->>'nature'='CONSUMED_PRICE_ADJUSTMENT'",eventId);UUID hotel=id(event.get("hotel_id"));scope(hotel);
  if(event.get("allocations")==null){issue(p,"PRICE_ADJUSTMENT",eventId,hotel,"已耗用采购发票价差已形成真实会计成本，仍需独立财务逐实际受益部门精确分配；不按采购默认部门猜，也不当作零费用");return;}
  for(var share:rows(event.get("allocations"))){BigDecimal actual=amount(share.get("amount"));if(Objects.toString(event.get("event_key")).startsWith("ADJUST_DOWN"))actual=actual.negate();UUID department=id(share.get("departmentId"));put(p,"PRICE_ADJUSTMENT",eventId,department,id(event.get("source_id")),hotel,id(event.get("source_company_id")),day(event.get("accounting_date")),share.get("financialCategoryCode").toString(),department,"EXPENSE",BigDecimal.ZERO,BigDecimal.ZERO,actual,BigDecimal.ZERO,0,Map.of("originalSourceEvent",eventId,"recognitionId",event.get("source_id"),"actualDepartmentShare",share,"noNewAccountingCost",true,"projectSnapshot",projectOf(share)),false);}
  resolved(p,"PRICE_ADJUSTMENT",eventId);
 }
 private boolean projectMatches(Map<String,Object> spec,String key){String kind=Objects.toString(spec.get("projectKind"),"ALL");return kind.equals("ALL")||key.equals(kind.equals("NONE")?"NONE":kind+":"+spec.get("projectId"));}
 private Map<String,Object> projectOf(Map<String,Object> source){Object raw=source.containsKey("finance_project_snapshot")?source.get("finance_project_snapshot"):source.containsKey("projectSnapshot")?source.get("projectSnapshot"):source.get("project_snapshot");var project=map(raw);return project.containsKey("key")?project:Map.of("kind","NONE","key","NONE");}
 private void put(TenantPrincipal p,String kind,UUID source,UUID line,UUID document,UUID hotel,UUID company,LocalDate day,String category,UUID department,String nature,BigDecimal inflight,BigDecimal committed,BigDecimal actual,BigDecimal inventory,long sourceVersion,Map<String,Object> snapshot,boolean enforce){
  jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(:key,103))",Map.of("key",p.tenantId()+":financial-budget"),Object.class);
  Map<String,Object> project=projectOf(snapshot);String projectKey=Objects.toString(project.get("key"),"NONE");if(!projectKey.equals("NONE")&&(!Objects.equals(id(project.get("hotelId")),hotel)||!Objects.equals(id(project.get("companyId")),company))){if(enforce)throw conflict("原冻结项目主体/门店与当前真实来源不一致，不允许跨项目跨主体挪用预算");issue(p,"PROJECT",source,hotel,"原冻结项目与实际费用来源主体/组织不一致，保留原真实成本并列待核对，不将未归集成本当零或改写项目");return;}LocalDate month=YearMonth.from(day).atDay(1);UUID id=key(p.tenantId()+":"+kind+":"+source+":"+line+":"+month+(projectKey.equals("NONE")?"":":"+projectKey));var b=base(p).addValue("id",id).addValue("hotel",hotel).addValue("company",company).addValue("kind",kind).addValue("source",source).addValue("line",line).addValue("document",document).addValue("month",month).addValue("category",category).addValue("department",department).addValue("nature",nature).addValue("inflight",inflight).addValue("committed",committed).addValue("actual",actual).addValue("inventory",inventory).addValue("sourceVersion",sourceVersion);
  var basis=new LinkedHashMap<String,Object>(snapshot);basis.put("inflight",inflight.toPlainString());basis.put("committed",committed.toPlainString());basis.put("actual",actual.toPlainString());basis.put("inventoryPurchaseFunding",inventory.toPlainString());basis.put("sourceVersion",sourceVersion);String hash=FinanceService.hash(json(new TreeMap<>(basis)));b.addValue("hash",hash).addValue("snapshot",json(basis));
  var old=jdbc.queryForList("select * from fbu_flow where tenant_id=:tenant and id=:id",b);if(!old.isEmpty()&&hash.equals(old.getFirst().get("source_hash")))return;if(!old.isEmpty()&&!kind.equals("PROCUREMENT"))throw conflict("预算真实成本来源已冻结，不覆盖原期；请保留原件追加受控差额");
  var policies=jdbc.queryForList("select * from fc_policy where tenant_id=:tenant and hotel_id=:hotel and kind='BUDGET' and status='PUBLISHED' and spec->>'month'=:ym order by id for update",b.addValue("ym",YearMonth.from(day).toString()));
  for(var policy:policies){var spec=map(policy.get("spec"));if(!category.equals(spec.get("categoryCode"))||!nature.equals(spec.get("budgetKind"))||spec.get("departmentId")!=null&&!Objects.toString(spec.get("departmentId")).isBlank()&&!Objects.equals(id(spec.get("departmentId")),department))continue;
   boolean applies=projectMatches(spec,projectKey),unknownSource=projectKey.equals("NONE")&&!"EXPLICIT_NONE".equals(project.get("designation"))&&inflight.add(committed).add(actual).add(nature.equals("INVENTORY")?inventory:BigDecimal.ZERO).signum()!=0;
   if(FinanceCostDimensions.projectsInstalled(jdbc)&&Set.of("CONTRACT","CIP").contains(Objects.toString(spec.get("projectKind"),"ALL"))&&(applies||unknownSource)){
    var unknown=base(p).addValue("hotel",hotel).addValue("month",month).addValue("category",category).addValue("nature",nature).addValue("department",department).addValue("allDepartments",spec.get("departmentId")==null||Objects.toString(spec.get("departmentId")).isBlank());
    boolean unresolved=unknownSource||jdbc.queryForObject("select coalesce(sum(inflight+committed+actual+case when basis_kind='INVENTORY' then inventory_value else 0 end),0)<>0 from fbu_flow where tenant_id=:tenant and hotel_id=:hotel and month=:month and category_code=:category and basis_kind=:nature and (:allDepartments or department_id=:department) and project_kind='NONE' and coalesce(project_snapshot->>'designation','')<>'EXPLICIT_NONE'",unknown,Boolean.class);
    if(unresolved){String message="项目专用预算存在同月、同类别/部门的历史未确证项目占用，不能按零额或其它项目排除。先核对原来源；已冻结且无受控归类路径的，须独立改用总预算或从下一期启用项目预算，此界面不能改写历史项目归属。";if(enforce)throw conflict(message);issue(p,"PROJECT_HISTORY",id(policy.get("id")),hotel,message);}else resolved(p,"PROJECT_HISTORY",id(policy.get("id")));
   }
   if(!applies)continue;
   // Inventory purchasing funds remain consumed after acceptance; this is not an expense or current stock valuation.
   BigDecimal occupied=jdbc.queryForObject("select coalesce(sum(inflight+committed+actual+case when basis_kind='INVENTORY' then inventory_value else 0 end),0) from fbu_flow where tenant_id=:tenant and hotel_id=:hotel and month=:month and category_code=:category and basis_kind=:nature and (:allDepartments or department_id=:department) and id<>:id"+(FinanceCostDimensions.projectsInstalled(jdbc)?" and (:allProjects or project_key=:projectKey)":""),b.addValue("allProjects",Objects.toString(spec.get("projectKind"),"ALL").equals("ALL")).addValue("projectKey",projectKey).addValue("allDepartments",spec.get("departmentId")==null||Objects.toString(spec.get("departmentId")).isBlank()),BigDecimal.class);
   BigDecimal claims=jdbc.queryForObject("select coalesce(sum(u.amount),0) from fc_budget_usage u join fc_policy q on q.tenant_id=u.tenant_id and q.id=u.policy_id where u.tenant_id=:tenant and q.hotel_id=:hotel and q.kind='BUDGET' and q.code=:policyCode and q.spec->>'month'=:ym and u.state<>'RELEASED'"+(FinanceCostDimensions.projectsInstalled(jdbc)?" and (:allProjects or u.project_key=:projectKey)":""),b.addValue("policyCode",policy.get("code")),BigDecimal.class);
   if(occupied.add(claims).add(inflight).add(committed).add(actual).add(nature.equals("INVENTORY")?inventory:BigDecimal.ZERO).compareTo(amount(spec.get("amount")))>0){if(enforce&&"BLOCK".equals(spec.get("control")))throw conflict("已发布预算不足，采购承诺须先经独立预算修订，不得绕过成本类别");guard.event(p,hotel,"BUDGET_SOURCE",source,"BUDGET_ACTUAL_WARNING",Map.of("policyId",policy.get("id"),"sourceKind",kind,"actual",actual.toPlainString(),"message","真实已发生费用照实保留，超预算仍待财务核对，不伪装审批通过"));}
  }
  if(old.isEmpty())jdbc.update("insert into fbu_flow(id,tenant_id,hotel_id,company_id,source_kind,source_id,line_id,document_id,month,category_code,department_id,basis_kind,inflight,committed,actual,inventory_value,source_version,source_hash,snapshot"+(FinanceCostDimensions.projectsInstalled(jdbc)?",project_kind,project_id,project_key,project_snapshot":"")+") values(:id,:tenant,:hotel,:company,:kind,:source,:line,:document,:month,:category,:department,:nature,:inflight,:committed,:actual,:inventory,:sourceVersion,:hash,cast(:snapshot as jsonb)"+(FinanceCostDimensions.projectsInstalled(jdbc)?",:projectKind,:projectId,:projectKey,cast(:projectSnapshot as jsonb)":"")+")",b.addValue("projectKind",project.get("kind")).addValue("projectId",id(project.get("id"))).addValue("projectKey",projectKey).addValue("projectSnapshot",json(project)));
  else jdbc.update("update fbu_flow set inflight=:inflight,committed=:committed,source_version=:sourceVersion,source_hash=:hash,snapshot=cast(:snapshot as jsonb),version=version+1,updated_at=now() where tenant_id=:tenant and id=:id",b);
  jdbc.update("insert into fbu_change(tenant_id,flow_id,actor_id,prior_snapshot,new_snapshot,note) values(:tenant,:id,:actor,cast(:prior as jsonb),cast(:snapshot as jsonb),'按真实来源承接预算，不替代原始业务/记账事实')",b.addValue("prior",json(old.isEmpty()?Map.of():output(old.getFirst()))));
 }
}
